function q(string $sql,array $p=[]): PDOStatement {global $db;$s=$db->prepare($sql);$s->execute($p);return $s;}
function one(string $sql,array $p=[]): ?array {$r=q($sql,$p)->fetch();return $r===false?null:$r;}
function all(string $sql,array $p=[]): array{return q($sql,$p)->fetchAll();}
function run(string $sql,array $p=[]): int{return q($sql,$p)->rowCount();}
function id(): string{return bin2hex(random_bytes(16));} function nowiso():string{return gmdate('Y-m-d\TH:i:s\Z');}
function body():array{$x=json_decode(file_get_contents('php://input'),true);return is_array($x)?$x:$_POST;}
function out($x,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function fail(string $m,int $s=400):never{out(['error'=>$m],$s);} function yes($v):bool{return $v==='true'||$v===true||$v===1||$v==='1';}
function setting(string $k,string $default=''):string{$r=one('SELECT value FROM settings WHERE key=?',[$k]);return $r['value']??$default;} function setsetting(string $k,string $v):void{q('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value',[$k,$v]);}
function admincheck():void{if(empty($_SESSION['isAdmin']))fail('Требуется вход администратора.',401);} function usercheck():array{if(empty($_SESSION['userId']))fail('Сначала зарегистрируйся или войди в аккаунт.',401);$u=one('SELECT * FROM users WHERE id=?',[$_SESSION['userId']]);if(!$u)fail('Аккаунт не найден.',401);if((bool)$u['is_banned']){session_destroy();fail('Аккаунт заблокирован администрацией.',403);}return $u;}
function nomdata():array{return array_map(fn($n)=>[$n['title'],(one('SELECT description FROM nomination_descriptions WHERE category=?',[$n['position']])['description']??$n['description']),$n['group_name']],all('SELECT title,description,group_name,position FROM nominations ORDER BY position'));}
function candidates():array{return array_map(function($c){$c['category']=(int)$c['category'];return $c;},all('SELECT id,category,name,image,bio,audio_url FROM candidates ORDER BY created_at ASC'));}
function counts():array{$o=[];foreach(all('SELECT candidate_id,COUNT(*) AS count FROM votes GROUP BY candidate_id') as $v)$o[$v['candidate_id']]=(int)$v['count'];return $o;}
function publicconfig():array{return ['votingOpen'=>setting('voting_open','true')==='true','timerEnabled'=>setting('timer_enabled')==='true','timerEnd'=>setting('timer_end'),'juryMode'=>setting('jury_mode')==='true'];}
function isjury(string $email):bool{$a=array_filter(array_map('trim',explode(',',getenv('JURY_EMAILS')?:'')));return in_array(strtolower($email),array_map('strtolower',$a),true);}
