CREATE TABLE IF NOT EXISTS candidates(id TEXT PRIMARY KEY,category INTEGER NOT NULL,name TEXT NOT NULL,image TEXT NOT NULL DEFAULT '',bio TEXT NOT NULL DEFAULT '',audio_url TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
