CREATE TABLE IF NOT EXISTS archives(id TEXT PRIMARY KEY,title TEXT NOT NULL,created_at TEXT NOT NULL,results_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nomination_descriptions(category INTEGER PRIMARY KEY,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nominations(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',group_name TEXT NOT NULL DEFAULT 'music',position INTEGER NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS chat_messages(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gifts(id TEXT PRIMARY KEY,name TEXT NOT NULL,emoji TEXT NOT NULL,price INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_gifts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),gift_id TEXT NOT NULL REFERENCES gifts(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS private_messages(id TEXT PRIMARY KEY,sender_id TEXT NOT NULL REFERENCES users(id),recipient_id TEXT NOT NULL REFERENCES users(id),message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS friendships(id TEXT PRIMARY KEY,requester_id TEXT NOT NULL REFERENCES users(id),addressee_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,UNIQUE(requester_id,addressee_id));
CREATE TABLE IF NOT EXISTS user_sessions(sid TEXT PRIMARY KEY,sess JSON NOT NULL,expire TIMESTAMP NOT NULL);
SQL);
// Store PHP sessions in PostgreSQL too: logins survive Render restarts and deploys.
final class PgSessionHandler implements SessionHandlerInterface {
  private PDO $pdo;
  public function __construct(PDO $pdo){$this->pdo=$pdo;}
  public function open(string $path,string $name):bool{return true;}
  public function close():bool{return true;}
  public function read(string $id):string|false{$s=$this->pdo->prepare('SELECT sess FROM user_sessions WHERE sid=? AND expire>NOW()');$s->execute([$id]);$v=$s->fetchColumn();if($v===false)return '';if(is_string($v)){ $j=json_decode($v,true);return is_string($j)?$j:$v;}return '';}
  public function write(string $id,string $data):bool{$s=$this->pdo->prepare("INSERT INTO user_sessions(sid,sess,expire) VALUES(?,CAST(? AS JSON),NOW()+INTERVAL '30 days') ON CONFLICT(sid) DO UPDATE SET sess=EXCLUDED.sess,expire=EXCLUDED.expire");return $s->execute([$id,json_encode($data)]);}
  public function destroy(string $id):bool{$s=$this->pdo->prepare('DELETE FROM user_sessions WHERE sid=?');return $s->execute([$id]);}
  public function gc(int $max_lifetime):int|false{$s=$this->pdo->prepare('DELETE FROM user_sessions WHERE expire<NOW()');$s->execute();return $s->rowCount();}
}
