  try{$old=new PDO('sqlite:'.__DIR__.'/migration/ksiva.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$db->beginTransaction();$tables=['gifts','nominations','nomination_descriptions','users','candidates','settings','votes','archives','chat_messages','user_gifts','private_messages','friendships'];$imported=0;
